diff --git a/src/core/util.c b/src/core/util.c
new file mode 100644
index 0000000..8caacf8
--- /dev/null
+++ b/src/core/util.c
@@ -0,0 +1,126 @@
+#include "core/util.h"
+
+#include <dirent.h>
+#include <errno.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
